#include <iostream>
#include <cmath>
using namespace std;

int main() {
    long long n;
    cin >> n;

    if (n < 0) {
        cout << "no";
        return 0;
    }

    __int128 d = static_cast<__int128>(8) * n + 1;
    long long root = static_cast<long long>(sqrtl(static_cast<long double>(d)));

    while (static_cast<__int128>(root) * root < d) ++root;
    while (static_cast<__int128>(root) * root > d) --root;

    cout << (static_cast<__int128>(root) * root == d ? "yes" : "no");
    return 0;
}

